import json

def array_sort(lists, order):
    result = []
    for lst in lists:
        if order == "ascending":
            sorted_lst = sorted(lst)
        else:
            sorted_lst = sorted(lst, reverse=True)
        result.append({"name": "array_sort", "parameters": {"list": lst, "order": order, "items": sorted_lst}})
    return json.dumps(result)

lists = [[45, 12, 67, 21, 89], [34, 78, 12, 56, 90], [23, 45, 67, 89, 12], [56, 78, 90, 12, 34]]
print(array_sort(lists, "ascending"))
print(array_sort(lists, "descending"))

